copy_shell_command:
$ErrorActionPreference = 'Stop'
$restoreWorkshop = (Get-Location).Path
$restoreSnapshot = Join-Path $restoreWorkshop '08_ARHIVA\ROM-001-G01\r01-before-audit'
$restoreSources = Join-Path $restoreSnapshot 'sources'
$restoreBase = [IO.Path]::GetFullPath((Join-Path $restoreWorkshop '09_RECUPERARI'))
$restoreLabel = 'ROM-001-G01-r01-before-' + [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssZ') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,8)
$restoreDestination = [IO.Path]::GetFullPath((Join-Path $restoreBase $restoreLabel))
if (-not $restoreBase.StartsWith($restoreWorkshop + '\',[StringComparison]::OrdinalIgnoreCase) -or -not $restoreDestination.StartsWith($restoreBase + '\',[StringComparison]::OrdinalIgnoreCase) -or $restoreDestination -eq $restoreBase) { throw 'Recovery target outside approved subtree' }
function Assert-Plain([string]$path) {
  $item = Get-Item -LiteralPath $path -Force
  $cursor = $item
  while ($cursor) {
    if ($cursor.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Reparse path refused: $path" }
    $cursor = if ($cursor.PSIsContainer) { $cursor.Parent } else { $cursor.Directory }
  }
  return $item
}
$null = Assert-Plain $restoreWorkshop
$null = Assert-Plain $restoreSources
if (Test-Path -LiteralPath $restoreBase) { $null = Assert-Plain $restoreBase }
if (Test-Path -LiteralPath $restoreDestination) { throw 'Unique recovery directory already exists; refusing reuse' }
$indexPath = Join-Path $restoreSnapshot 'index.json'
$indexHash = (Get-FileHash -LiteralPath $indexPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($indexHash -ne '73befab70d1266a41f79a339ce00eadb00d32efd57c5afdf9eb9ea7817c99823') { throw 'Snapshot index changed before copy' }
$index = Get-Content -LiteralPath $indexPath -Raw -Encoding UTF8 | ConvertFrom-Json
$sourceEntries = @($index.entries | Where-Object path -like 'sources/*')
$sourceNames = @($sourceEntries | ForEach-Object { $_.path.Substring(8) })
$queue = [Collections.Generic.Queue[string]]::new()
$queue.Enqueue($restoreSources)
$actualSourceNames = [Collections.Generic.List[string]]::new()
while ($queue.Count) {
  foreach ($item in Get-ChildItem -LiteralPath $queue.Dequeue() -Force) {
    $null = Assert-Plain $item.FullName
    if (-not $item.FullName.StartsWith($restoreSources + '\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Unsafe source path' }
    if ($item.PSIsContainer) { $queue.Enqueue($item.FullName) }
    else { $actualSourceNames.Add($item.FullName.Substring($restoreSources.Length+1).Replace('\','/')) }
  }
}
if (@(Compare-Object $sourceNames @($actualSourceNames)).Count) { throw 'Source tree does not exactly match index' }
$started = [DateTime]::UtcNow.ToString('o')
if (-not (Test-Path -LiteralPath $restoreBase)) { $null = New-Item -Path $restoreBase -ItemType Directory }
$null = Assert-Plain $restoreBase
$null = New-Item -Path $restoreDestination -ItemType Directory
$null = Assert-Plain $restoreDestination
foreach ($top in Get-ChildItem -LiteralPath $restoreSources -Force) {
  $null = Assert-Plain $top.FullName
  $null = Assert-Plain $restoreDestination
  Copy-Item -LiteralPath $top.FullName -Destination $restoreDestination -Recurse -ErrorAction Stop
}
$restoredNames = [Collections.Generic.List[string]]::new()
$queue.Enqueue($restoreDestination)
$restoredDirectoryCount = 0
while ($queue.Count) {
  foreach ($item in Get-ChildItem -LiteralPath $queue.Dequeue() -Force) {
    $null = Assert-Plain $item.FullName
    if (-not $item.FullName.StartsWith($restoreDestination + '\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Recovery path escaped target' }
    if ($item.PSIsContainer) { $restoredDirectoryCount++; $queue.Enqueue($item.FullName) }
    else { $restoredNames.Add($item.FullName.Substring($restoreDestination.Length+1).Replace('\','/')) }
  }
}
if (@(Compare-Object $sourceNames @($restoredNames)).Count) { throw 'Recovered file set differs from indexed sources' }
$recoveredBytes = [long]0
$mismatches = @(foreach ($entry in $sourceEntries) {
  $relative = $entry.path.Substring(8)
  $path = [IO.Path]::GetFullPath((Join-Path $restoreDestination $relative))
  if (-not $path.StartsWith($restoreDestination + '\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Recovery traversal' }
  $item = Assert-Plain $path
  $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()
  $recoveredBytes += $item.Length
  if ($hash -ne $entry.sha256 -or $item.Length -ne $entry.size_bytes) { [PSCustomObject]@{path=$relative;actual_sha256=$hash;expected_sha256=$entry.sha256;actual_bytes=$item.Length;expected_bytes=$entry.size_bytes} }
})
if ($mismatches.Count) { throw ('Recovered mismatches: ' + ($mismatches | ConvertTo-Json -Compress)) }
$gate = Join-Path $restoreDestination '04_INSTRUMENTE\gatekeeper.py'
$restoredRegistry = Get-Content -LiteralPath (Join-Path $restoreDestination '06_REGISTRU\deliverables.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$deliverable = @($restoredRegistry.deliverables | Where-Object id -eq 'ROM-001-G01')
if ($deliverable.Count -ne 1) { throw 'Restored deliverable ID not unique' }
$contractPath = Join-Path $restoreDestination $deliverable[0].contract.path
$contractHash = (Get-FileHash -LiteralPath $contractPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($contractHash -ne '07110637be555cb455727593ebdf9ef88de1f27c12b5a389f53e79544bd6cebe') { throw 'Recovered contract mismatch' }
$contract = Get-Content -LiteralPath $contractPath -Raw -Encoding UTF8 | ConvertFrom-Json
[PSCustomObject]@{
 started_at=$started;finished_at=[DateTime]::UtcNow.ToString('o');source_tree=$restoreSources;recovered_root=$restoreDestination;approved_parent=$restoreBase;
 absolute_target_validated_before_creation=$true;fresh_directory=$true;preserved_without_cleanup=$true;copy_method='Copy-Item -LiteralPath $top.FullName -Destination $restoreDestination -Recurse -ErrorAction Stop; top-level children of snapshot/sources only';
 restored_files=$restoredNames.Count;indexed_source_files=$sourceEntries.Count;directories=$restoredDirectoryCount;bytes=$recoveredBytes;
 exact_indexed_file_set=$true;all_hashes_and_sizes_match_index=$true;no_reparse_paths=$true;mismatches=$mismatches;
 validator_path=$gate;validator_sha256=(Get-FileHash -LiteralPath $gate -Algorithm SHA256).Hash.ToLowerInvariant();
 restored_registry_sha256=(Get-FileHash -LiteralPath (Join-Path $restoreDestination '06_REGISTRU\deliverables.json') -Algorithm SHA256).Hash.ToLowerInvariant();
 version_id=$deliverable[0].version_id;stage=$deliverable[0].stage;registered_status=$deliverable[0].status;contract=$deliverable[0].contract;contract_sha256=$contractHash;contract_schema_version=$contract.schema_version;contract_deliverable_id=$contract.deliverable_id;
 artifact_files=$deliverable[0].files.Count;evidence_files=$deliverable[0].evidence_files.Count;dependencies=$deliverable[0].dependencies;
 declared_audits=$deliverable[0].audits;meta_audit_declared=($deliverable[0].PSObject.Properties.Name -contains 'meta_audit')
} | ConvertTo-Json -Depth 8
